package com.taskflow.pro;
import android.app.*;import android.widget.Toast;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity {
 WebView web; String pendingBackup;
 @Override public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);setContentView(web);web.setOnApplyWindowInsetsListener((v,i)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=i.getInsets(android.view.WindowInsets.Type.systemBars() | android.view.WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}return i;});web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.addJavascriptInterface(new Bridge(),"Native");web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(r.getUrl().toString().equals("https://app.taskflow.local/")){try{return new WebResourceResponse("text/html","UTF-8",getAssets().open("index.html"));}catch(Exception e){}}return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}});web.loadUrl("https://app.taskflow.local/");}
 public class Bridge {
 @JavascriptInterface public String load(){return getSharedPreferences("taskflow",0).getString("data","");}
 @JavascriptInterface public boolean save(String s){return getSharedPreferences("taskflow",0).edit().putString("data",s).commit();}
 @JavascriptInterface public void exportData(String s){pendingBackup=s;runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"TaskFlow-backup.json");startActivityForResult(i,10);});}
 @JavascriptInterface public void importData(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,11);});}
 }
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;try {if(req==10){try(OutputStream o=getContentResolver().openOutputStream(data.getData())){o.write(pendingBackup.getBytes(StandardCharsets.UTF_8));}toast("Backup saved");}else if(req==11){try(InputStream in=getContentResolver().openInputStream(data.getData());ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){o.write(buf,0,n);if(o.size()>10*1024*1024)throw new IOException("Backup exceeds 10 MB");}String json=o.toString("UTF-8");web.evaluateJavascript("window.restoreBackup("+org.json.JSONObject.quote(json)+")",null);}}}catch(Exception e){toast("Could not read or write backup. Please try another file.");}}
 @Override public void onBackPressed(){web.evaluateJavascript("window.handleBack()",r->{if("false".equals(r))super.onBackPressed();});}
}
